        [DllImport(Lib, EntryPoint = "TJAREX_GetCameraImageInfo", CallingConvention = CallingConvention.Cdecl)]
        public static extern int GetCameraImageInfo(out int outWidth, out int outHeight, out int outFormat, out int outPlaneCount);

        /// <summary>Copies one YUV plane. Returns bytes copied, or negative on failure.</summary>
        [DllImport(Lib, EntryPoint = "TJAREX_CopyCameraImagePlane", CallingConvention = CallingConvention.Cdecl)]
        public static extern int CopyCameraImagePlane(int planeIndex, [Out] byte[] outBuffer, int maxBytes, out int outRowStride, out int outPixelStride, out int outDataLength);

        /// <summary>Hands out the SDK's own pointer to one YUV plane instead of copying it, for callers that need a particular row order or must skip row-stride padding and would otherwise pay for a second full-image copy. Writes the row stride, pixel stride and byte length. The pointer is borrowed: it stays valid only until TJAREX_ReleaseCameraImage. Returns 0, or negative on failure.</summary>
        [DllImport(Lib, EntryPoint = "TJAREX_GetCameraImagePlaneData", CallingConvention = CallingConvention.Cdecl)]
        public static extern int GetCameraImagePlaneData(int planeIndex, out IntPtr outData, out int outRowStride, out int outPixelStride, out int outDataLength);

