        #region Tuanjie / Unity render-thread entry point

        [DllImport(Lib, EntryPoint = "TJAREX_GetRenderEventFunc", CallingConvention = CallingConvention.Cdecl)]
        public static extern IntPtr GetRenderEventFunc();

        /// <summary>Marks one issued event as pending. Begin and Wait must be called from the same (main) thread, once each per issued event.</summary>
        [DllImport(Lib, EntryPoint = "TJAREX_BeginRenderEvent", CallingConvention = CallingConvention.Cdecl)]
        public static extern void BeginRenderEvent();

        /// <summary>Blocks the calling thread until the render thread has finished every pending event. Returns 1 when they all completed, 0 on timeout. Keep timeoutMs short (one frame is enough); a timeout clears the pending count rather than wedging every later frame.</summary>
        [DllImport(Lib, EntryPoint = "TJAREX_WaitForRenderEvent", CallingConvention = CallingConvention.Cdecl)]
        public static extern int WaitForRenderEvent(int timeoutMs);

        #endregion
    }
}
